<script setup>
import { computed, ref, watch } from 'vue';

const props=defineProps({mode:{type:String,required:true},completado:{type:Boolean,default:false}});const emit=defineEmits(['hablar','practicar']);
const paso=ref(1),sujetoId=ref('i'),lugarId=ref('office'),verboId=ref('fix'),accionId=ref('write'),interrupcionId=ref('call'),retoIdx=ref(0),elegida=ref(null),aciertos=ref(new Set());
const sujetos=[{id:'i',texto:'I',be:'was',icono:'🙋'},{id:'you',texto:'You',be:'were',icono:'👉'},{id:'she',texto:'She',be:'was',icono:'👩'},{id:'he',texto:'He',be:'was',icono:'👨'},{id:'we',texto:'We',be:'were',icono:'👥'},{id:'they',texto:'They',be:'were',icono:'🧑‍🤝‍🧑'}];
const lugares=[{id:'office',texto:'at the office',icono:'🏢'},{id:'home',texto:'at home',icono:'🏠'},{id:'meeting',texto:'in a meeting',icono:'🗣️'},{id:'vacation',texto:'on vacation',icono:'🏖️'}];
const verbos=[{id:'fix',base:'fix',past:'fixed',tipo:'regular',icono:'🐛',objeto:'the bug'},{id:'merge',base:'merge',past:'merged',tipo:'regular',icono:'🔀',objeto:'the changes'},{id:'study',base:'study',past:'studied',tipo:'regular',icono:'📚',objeto:'English'},{id:'go',base:'go',past:'went',tipo:'irregular',icono:'🚶',objeto:'home'},{id:'break',base:'break',past:'broke',tipo:'irregular',icono:'💥',objeto:'the build'},{id:'write',base:'write',past:'wrote',tipo:'irregular',icono:'✍️',objeto:'the report'}];
const acciones=[{id:'write',ing:'writing the report',icono:'✍️'},{id:'deploy',ing:'deploying the app',icono:'🚀'},{id:'debug',ing:'debugging the issue',icono:'🔎'},{id:'monitor',ing:'monitoring the servers',icono:'📡'}];
const interrupciones=[{id:'call',texto:'you called',icono:'📞'},{id:'alert',texto:'the alert fired',icono:'🚨'},{id:'crash',texto:'the database crashed',icono:'💥'},{id:'drop',texto:'the connection dropped',icono:'📴'}];
const sujeto=computed(()=>sujetos.find(x=>x.id===sujetoId.value)),lugar=computed(()=>lugares.find(x=>x.id===lugarId.value)),verbo=computed(()=>verbos.find(x=>x.id===verboId.value)),accion=computed(()=>acciones.find(x=>x.id===accionId.value)),interrupcion=computed(()=>interrupciones.find(x=>x.id===interrupcionId.value));
const fraseWas=computed(()=>`${sujeto.value.texto} ${sujeto.value.be} ${lugar.value.texto} yesterday.`);const fraseSimple=computed(()=>`${sujeto.value.texto} ${verbo.value.past} ${verbo.value.objeto} yesterday.`);const fraseContinua=computed(()=>`${sujeto.value.texto} ${sujeto.value.be} ${accion.value.ing} when ${interrupcion.value.texto}.`);
const titulos=computed(()=>props.mode==='was-were'?{icono:'📸',sobre:'RECUERDOS',titulo:'Was / were: una foto del pasado',bajada:'Estados y lugares que ya quedaron atrás.',tabs:['Armá un recuerdo','Mapa was / were','Desafío de memoria']}:props.mode==='simple'?{icono:'⏮️',sobre:'ACCIÓN TERMINADA',titulo:'Pasado simple: ocurrió y terminó',bajada:'Acciones completas en un momento del pasado.',tabs:['Máquina de verbos','Contá qué pasó','Desafío del ayer']}:{icono:'🎬',sobre:'ESCENA EN PROGRESO',titulo:'Pasado continuo: la acción estaba ocurriendo',bajada:'Una escena en curso que otra acción puede interrumpir.',tabs:['Director de escena','Línea de tiempo','Desafío when / while']});
const retosPorModo={
  'was-were':[
    {icono:'❓',frase:'___ you at the standup this morning?',respuesta:'Were',opciones:['Was','Were','Did','Are'],ayuda:'You siempre va con were.'},{icono:'🚀',frase:'The deploy ___ successful last night.',respuesta:'was',opciones:['was','were','is','did'],ayuda:'The deploy es singular: was.'},{icono:'👥',frase:'They ___ in a meeting.',respuesta:'were',opciones:['was','were','are','did'],ayuda:'They va con were.'},{icono:'🙋',frase:'I ___ not ready yesterday.',respuesta:'was',opciones:['were','am','was','did'],ayuda:'I va con was.'}],
  simple:[
    {icono:'🐛',frase:'The bug ___ after the deploy.',respuesta:'appeared',opciones:['appear','appeared','appears','appearing'],ayuda:'Verbo regular: appear + ed.'},{icono:'🚶',frase:'She ___ home after work.',respuesta:'went',opciones:['goed','went','gone','go'],ayuda:'Go es irregular: go → went.'},{icono:'💥',frase:'The pipeline ___ twice yesterday.',respuesta:'broke',opciones:['breaked','broken','broke','break'],ayuda:'Break es irregular: break → broke.'},{icono:'🚫',frase:"I ___ that case before release.",respuesta:"didn't test",opciones:["didn't tested","didn't test","not tested","don't test"],ayuda:"Después de didn't usamos la forma base."}],
  continuous:[
    {icono:'🚀💥',frase:'We ___ when the database crashed.',respuesta:'were deploying',opciones:['deployed','were deploying','was deploying','deploy'],ayuda:'We usa were + verbo-ing.'},{icono:'✍️📞',frase:'I ___ when you called.',respuesta:'was writing',opciones:['wrote','were writing','was writing','write'],ayuda:'I usa was + verbo-ing.'},{icono:'🔎🚨',frase:'While she ___, another alert fired.',respuesta:'was debugging',opciones:['debugged','were debugging','was debugging','debugs'],ayuda:'She usa was; while presenta la acción en curso.'},{icono:'📡🌙',frase:'They ___ the servers all night.',respuesta:'were monitoring',opciones:['monitored','was monitoring','were monitoring','monitor'],ayuda:'They usa were + verbo-ing.'}]
};
const retos=computed(()=>retosPorModo[props.mode]),reto=computed(()=>retos.value[retoIdx.value]),correcta=computed(()=>elegida.value===reto.value.respuesta);
function escuchar(t){emit('hablar',t,1)}function responder(o){elegida.value=o;if(o===reto.value.respuesta){const s=new Set(aciertos.value);s.add(retoIdx.value);aciertos.value=s}}function siguiente(){retoIdx.value=(retoIdx.value+1)%retos.value.length;elegida.value=null}watch(()=>props.mode,()=>{paso.value=1;retoIdx.value=0;elegida.value=null;aciertos.value=new Set()});
</script>

<template><section class="past" :class="`past--${mode}`"><aside class="hero"><span>{{titulos.icono}}</span><div><small>{{titulos.sobre}}</small><h2>{{titulos.titulo}}</h2><p>{{titulos.bajada}}</p></div><div class="time-stamp">YESTERDAY<br><b>← NOW</b></div></aside><nav><button v-for="(tab,i) in titulos.tabs" :key="tab" :class="{active:paso===i+1}" @click="paso=i+1"><b>0{{i+1}}</b><span>{{tab}}</span></button></nav>

<main v-if="mode==='was-were' && paso===1"><header><small>WAS / WERE 1</small><h3>Constructor de recuerdos</h3><p>Elegí quién y dónde estaba. La cámara arma la oración.</p></header><div class="builder"><section><button v-for="x in sujetos" :key="x.id" :class="{active:sujetoId===x.id}" @click="sujetoId=x.id"><span>{{x.icono}}</span><b>{{x.texto}}</b></button></section><section><button v-for="x in lugares" :key="x.id" :class="{active:lugarId===x.id}" @click="lugarId=x.id"><span>{{x.icono}}</span><b>{{x.texto}}</b></button></section></div><article class="result"><span>{{sujeto.icono}} {{lugar.icono}}</span><small>MEMORY CAPTURED</small><strong>{{fraseWas}}</strong><button @click="escuchar(fraseWas)">🔊 Escuchar recuerdo</button></article></main>
<main v-else-if="mode==='was-were' && paso===2"><header><small>WAS / WERE 2</small><h3>Dos equipos, una regla</h3><p>Seleccioná un pronombre para iluminar su forma pasada.</p></header><div class="teams"><article><b>WAS</b><button v-for="x in sujetos.filter(s=>s.be==='was')" :key="x.id" :class="{active:sujetoId===x.id}" @click="sujetoId=x.id">{{x.icono}} {{x.texto}}</button><span>I · he · she · it</span></article><article><b>WERE</b><button v-for="x in sujetos.filter(s=>s.be==='were')" :key="x.id" :class="{active:sujetoId===x.id}" @click="sujetoId=x.id">{{x.icono}} {{x.texto}}</button><span>you · we · they</span></article></div><div class="formula"><b>{{sujeto.texto}}</b><i>＋</i><strong>{{sujeto.be}}</strong><i>＋</i><span>complement</span></div><aside class="note"><b>Negación:</b> was not / wasn't · were not / weren't &nbsp; <b>Pregunta:</b> Was she…? · Were they…?</aside></main>

<main v-else-if="mode==='simple' && paso===1"><header><small>PASADO SIMPLE 1</small><h3>Máquina del tiempo verbal</h3><p>Tocá un verbo: algunos siguen la ruta -ed y otros cambian por completo.</p></header><div class="verb-machine"><section><button v-for="x in verbos" :key="x.id" :class="{active:verboId===x.id}" @click="verboId=x.id"><span>{{x.icono}}</span><b>{{x.base}}</b><small>{{x.tipo}}</small></button></section><article><small>BASE</small><b>{{verbo.base}}</b><i>{{verbo.tipo==='regular'?'+ ed':'cambio irregular'}}</i><em>→</em><small>PAST</small><strong>{{verbo.past}}</strong><button @click="escuchar(`Yesterday I ${verbo.past} ${verbo.objeto}.`)">🔊 Escuchar</button></article></div><div class="mini-rules"><span><b>+ ed</b>work → worked</span><span><b>-e + d</b>merge → merged</span><span><b>y → ied</b>study → studied</span><span><b>Irregular</b>go → went</span></div></main>
<main v-else-if="mode==='simple' && paso===2"><header><small>PASADO SIMPLE 2</small><h3>Crónica del ayer</h3><p>Combiná personaje y acción para crear un hecho terminado.</p></header><div class="builder"><section><button v-for="x in sujetos" :key="x.id" :class="{active:sujetoId===x.id}" @click="sujetoId=x.id">{{x.icono}} <b>{{x.texto}}</b></button></section><section><button v-for="x in verbos" :key="x.id" :class="{active:verboId===x.id}" @click="verboId=x.id">{{x.icono}} <b>{{x.past}}</b></button></section></div><article class="result"><span>{{sujeto.icono}} {{verbo.icono}}</span><small>COMPLETED EVENT</small><strong>{{fraseSimple}}</strong><button @click="escuchar(fraseSimple)">🔊 Escuchar historia</button></article><aside class="note"><b>Pregunta:</b> Did + subject + base? &nbsp; <b>Negación:</b> didn't + base. Después de <i>did</i>, el verbo pierde el pasado.</aside></main>

<main v-else-if="mode==='continuous' && paso===1"><header><small>PASADO CONTINUO 1</small><h3>Director de escenas</h3><p>Construí una acción en progreso y elegí qué la interrumpió.</p></header><div class="director"><section><button v-for="x in sujetos" :key="x.id" :class="{active:sujetoId===x.id}" @click="sujetoId=x.id">{{x.icono}} {{x.texto}}</button></section><section><button v-for="x in acciones" :key="x.id" :class="{active:accionId===x.id}" @click="accionId=x.id">{{x.icono}} {{x.ing}}</button></section><section><button v-for="x in interrupciones" :key="x.id" :class="{active:interrupcionId===x.id}" @click="interrupcionId=x.id">{{x.icono}} {{x.texto}}</button></section></div><article class="result cinema"><span>{{sujeto.icono}} {{accion.icono}} ⚡ {{interrupcion.icono}}</span><small>PAST SCENE</small><strong>{{fraseContinua}}</strong><button @click="escuchar(fraseContinua)">🔊 Reproducir escena</button></article></main>
<main v-else-if="mode==='continuous' && paso===2"><header><small>PASADO CONTINUO 2</small><h3>Una línea, dos velocidades</h3><p>La acción larga estaba en progreso; la acción corta ocurrió de repente.</p></header><div class="timeline"><span>PAST</span><article><b>was / were + -ing</b><i>──────────────</i><small>acción en progreso</small></article><em>⚡ WHEN</em><article><b>past simple</b><i>●</i><small>interrupción</small></article><span>NOW</span></div><div class="examples"><button @click="escuchar('I was writing when you called.')"><b>I was writing</b><span>when you called.</span> 🔊</button><button @click="escuchar('While they were deploying, the database crashed.')"><b>While they were deploying,</b><span>the database crashed.</span> 🔊</button></div><aside class="note"><b>while</b> suele presentar la acción larga; <b>when</b> introduce el momento o la interrupción.</aside></main>

<main v-else><header class="challenge-head"><div><small>{{titulos.sobre}} · RETO</small><h3>{{titulos.tabs[2]}}</h3><p>Usá la pista temporal y el sujeto antes de responder.</p></div><b>{{aciertos.size}}/{{retos.length}}</b></header><article class="challenge"><span>{{reto.icono}}</span><button @click="escuchar(reto.frase.replace('___',reto.respuesta))">{{reto.frase}} 🔊</button><div><button v-for="o in reto.opciones" :key="o" :class="{ok:elegida&&o===reto.respuesta,bad:elegida===o&&o!==reto.respuesta}" @click="responder(o)">{{o}}</button></div><p v-if="elegida"><b>{{correcta?'✓ Viajaste bien en el tiempo':'↻ Revisá la pista'}}</b> {{reto.ayuda}}</p><button v-if="correcta" class="next" @click="siguiente">Siguiente recuerdo →</button></article></main>
<button class="practice" :disabled="completado" @click="emit('practicar')">{{completado?'✓ Ejercicios ya acreditados':'Practicar ejercicios del workbook →'}}</button></section></template>

<style scoped>
.past{display:grid;gap:1rem;--past:#8a5637;--soft:#fff1e5;--soft2:#edf5ff}.past--simple{--past:#7952a5;--soft:#f3edfb}.past--continuous{--past:#276c81;--soft:#e9f6fa}.hero,main{padding:1rem;border:1px solid #ddc7b8;border-radius:18px;background:#fff}.hero{display:grid;grid-template-columns:auto 1fr auto;align-items:center;gap:.8rem;background:linear-gradient(135deg,var(--soft),var(--soft2))}.hero>span{font-size:2.6rem}.hero h2,main h3{margin:.15rem 0}.hero p,main header p{margin:.25rem 0;color:var(--color-texto-secundario)}small{font-size:.62rem;font-weight:900;letter-spacing:.08em;color:var(--past)}.time-stamp{padding:.55rem;border:1px dashed var(--past);border-radius:10px;color:var(--past);font-size:.65rem;text-align:center;transform:rotate(2deg)}nav{display:grid;grid-template-columns:repeat(3,1fr);gap:.5rem}nav button{display:flex;gap:.5rem;padding:.7rem;border:1px solid var(--color-borde);border-radius:12px;background:#fff}nav button b{color:var(--past)}nav button.active{border-color:var(--past);background:var(--soft)}.builder,.director{display:grid;gap:.6rem}.builder section,.director section{display:flex;flex-wrap:wrap;gap:.4rem}.builder button,.director button,.verb-machine section button{display:flex;align-items:center;gap:.25rem;padding:.5rem .65rem;border:1px solid var(--color-borde);border-radius:9px;background:#fff}.builder button.active,.director button.active,.verb-machine button.active,.teams button.active{border-color:var(--past)!important;background:var(--soft)!important}.result{display:flex;flex-direction:column;align-items:center;margin-top:.8rem;padding:1rem;border-radius:15px;background:linear-gradient(145deg,var(--soft),var(--soft2));text-align:center}.result>span{font-size:2.4rem}.result strong{font:italic 1.2rem Georgia}.result button,.verb-machine article button{margin-top:.5rem;padding:.5rem .7rem;border:0;border-radius:8px;background:var(--past);color:#fff}.teams{display:grid;grid-template-columns:1fr 1fr;gap:.7rem}.teams article{display:flex;flex-wrap:wrap;gap:.4rem;padding:1rem;border-radius:15px;background:var(--soft)}.teams article>b,.teams article>span{width:100%}.teams button{padding:.45rem;border:1px solid var(--color-borde);border-radius:8px;background:#fff}.formula{display:flex;justify-content:center;align-items:center;gap:.7rem;margin:.8rem 0;padding:1rem;border-radius:12px;background:var(--soft2)}.formula strong{font:italic 1.4rem Georgia;color:var(--past)}.note{padding:.7rem;border-left:4px solid var(--past);border-radius:8px;background:var(--soft);font-size:.75rem}.verb-machine{display:grid;grid-template-columns:1fr 1fr;gap:1rem}.verb-machine>section{display:grid;grid-template-columns:repeat(3,1fr);gap:.4rem}.verb-machine section button{flex-direction:column}.verb-machine article{display:grid;grid-template-columns:1fr auto 1fr;align-items:center;padding:1rem;border-radius:15px;background:var(--soft);text-align:center}.verb-machine article em{grid-row:1/4;grid-column:2}.verb-machine article>b,.verb-machine article>strong{font:italic 1.35rem Georgia}.verb-machine article button{grid-column:1/-1}.mini-rules{display:grid;grid-template-columns:repeat(4,1fr);gap:.4rem;margin-top:.7rem}.mini-rules span{display:flex;flex-direction:column;padding:.55rem;border:1px solid var(--color-borde);border-radius:9px;font-size:.7rem}.cinema{background:linear-gradient(145deg,#e5f4f7,#fff1df)}.timeline{display:grid;grid-template-columns:auto 2fr auto 1fr auto;align-items:center;gap:.5rem;margin:1rem 0;padding:1rem;border-radius:14px;background:var(--soft2)}.timeline article{display:flex;flex-direction:column;text-align:center}.timeline article i{color:var(--past);font-size:1.2rem}.timeline em{color:#d75c45;font-weight:900}.examples{display:grid;grid-template-columns:1fr 1fr;gap:.5rem}.examples button{display:flex;flex-direction:column;padding:.75rem;border:1px solid var(--color-borde);border-radius:10px;background:#fff}.challenge-head{display:flex;justify-content:space-between}.challenge-head>b{display:grid;place-items:center;width:48px;height:48px;border-radius:50%;background:var(--soft);color:var(--past)}.challenge{max-width:650px;margin:auto;padding:1rem;border-radius:16px;background:linear-gradient(145deg,var(--soft),var(--soft2));text-align:center}.challenge>span{font-size:2.7rem}.challenge>button{display:block;margin:.4rem auto;border:0;background:transparent;font:italic 1.15rem Georgia}.challenge>div{display:grid;grid-template-columns:1fr 1fr;gap:.4rem}.challenge>div button{padding:.6rem;border:1px solid var(--color-borde);border-radius:9px;background:#fff}.challenge .ok{border-color:var(--color-verde);background:var(--color-verde-suave)}.challenge .bad{border-color:#d26b54;background:#fff0ea}.next{background:var(--past)!important;color:#fff!important;padding:.55rem .8rem!important}.practice{width:100%;padding:.8rem;border:0;border-radius:var(--radio-boton);background:var(--past);color:#fff;font-weight:800}.practice:disabled{background:var(--color-verde)}
@media(max-width:700px){.verb-machine{grid-template-columns:1fr}.timeline{grid-template-columns:1fr}.mini-rules{grid-template-columns:1fr 1fr}}@media(max-width:520px){.hero{grid-template-columns:auto 1fr}.time-stamp{grid-column:1/-1}nav,.teams,.examples,.challenge>div{grid-template-columns:1fr}.verb-machine>section{grid-template-columns:1fr 1fr}.mini-rules{grid-template-columns:1fr}}
</style>
